input.sparql:
SELECT ?z WHERE {
  ?z a brick:Zone .
  FILTER(str(?z) LIKE "%Perimeter_top_ZN_3%")
}

SELECT ?point ?pred ?obj ?lbl WHERE {
  ?point rdf:type brick:OccupancySensor .
  OPTIONAL { ?point rdfs:label ?lbl }
  ?point ?pred ?obj .
}

SELECT ?p ?lbl WHERE {
  ?p rdf:type ?t .
  FILTER(str(?t) CONTAINS "Occupancy" || str(?t) CONTAINS "People")
  OPTIONAL { ?p rdfs:label ?lbl }
}

SELECT ?p ?t ?lbl WHERE {
  ?p rdf:type ?t .
  FILTER(CONTAINS(str(?t), "Occupancy"))
  OPTIONAL { ?p rdfs:label ?lbl }
}
